/// One sRGB colour as the console's CSS writes it: channels 0-255, alpha 0-1.
public struct LTRGBA: Sendable, Equatable {
    public let red: Double
    public let green: Double
    public let blue: Double
    public let alpha: Double

    public init(_ red: Double, _ green: Double, _ blue: Double, _ alpha: Double = 1) {
        self.red = red
        self.green = green
        self.blue = blue
        self.alpha = alpha
    }
}

/// A step of the console's type scale, drawn in the system font (SF Pro).
public struct LTTypeStep: Sendable, Equatable {
    public let size: CGFloat
    public let lineHeight: CGFloat
    /// CSS weight: 400 regular, 500 medium, 600 semibold.
    public let weight: Int
    public let trackingEm: CGFloat

    public var font: Font { .system(size: size, weight: fontWeight) }
    /// Letter spacing in points, for .tracking().
    public var tracking: CGFloat { trackingEm * size }
    public var fontWeight: Font.Weight {
        switch weight {
        case ..<450: return .regular
        case ..<550: return .medium
        case ..<650: return .semibold
        default: return .bold
        }
    }
}

public enum LTTokens {
    /// A colour that follows the system appearance: the light value in light mode, the dark value in dark mode.
    public static func dynamic(light: LTRGBA, dark: LTRGBA) -> Color {
        #if canImport(UIKit)
        return Color(uiColor: UIColor { traits in
            let value = traits.userInterfaceStyle == .dark ? dark : light
            return UIColor(red: value.red / 255, green: value.green / 255, blue: value.blue / 255, alpha: value.alpha)
        })
        #else
        return Color(nsColor: NSColor(name: nil) { appearance in
            let value = appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua ? dark : light
            return NSColor(srgbRed: value.red / 255, green: value.green / 255, blue: value.blue / 255, alpha: value.alpha)
        })
        #endif
    }

